use ctor::{Assign, CtorNew};
use googletest::prelude::*;
use proto_cpp::{Cpp, CppProto};
use protobuf::prelude::*;
use test_rust_proto::DummyMessage;

// Simulated ZST marker type as generated by `rs_bindings_from_cc` under
// `<cc_library>::proto::test_proto::DummyMessage`.
pub struct TestDummyMessage {
    _private: (),
}
// SAFETY: `Storage` matches `proto2::crubit_test::DummyMessage` (`sizeof == 32`, `alignof == 8`
// on 64-bit; `sizeof == 20`, `alignof == 4` on 32-bit; `crubit_protobuf_placement_new` asserts
// this at runtime).
unsafe impl CppProto for TestDummyMessage {
    type Message = DummyMessage;
    #[cfg(target_pointer_width = "64")]
    type Storage = proto_cpp::internal::RawStorage<32, 8>;
    #[cfg(target_pointer_width = "32")]
    type Storage = proto_cpp::internal::RawStorage<20, 4>;
}

// Second marker type representing the same proto message from a different C++ library's bindings.
pub struct OtherLibDummyMessage {
    _private: (),
}
// SAFETY: Same C++ protobuf message layout as `TestDummyMessage`.
unsafe impl CppProto for OtherLibDummyMessage {
    type Message = DummyMessage;
    #[cfg(target_pointer_width = "64")]
    type Storage = proto_cpp::internal::RawStorage<32, 8>;
    #[cfg(target_pointer_width = "32")]
    type Storage = proto_cpp::internal::RawStorage<20, 4>;
}

type InlineDummyMessage = Cpp<TestDummyMessage>;

#[gtest]
fn test_default_construction_and_mutation() {
    let mut inline_proto = ctor::emplace!(InlineDummyMessage::ctor_new(()));
    expect_that!(inline_proto.as_view().count(), eq(0));
    expect_that!(inline_proto.as_view().has_count(), eq(false));

    inline_proto.as_mut().as_proto_mut().set_count(42);
    expect_that!(inline_proto.as_view().count(), eq(42));
    expect_that!(inline_proto.as_view().has_count(), eq(true));

    inline_proto.as_mut().as_proto_mut().clear();
    expect_that!(inline_proto.as_view().count(), eq(0));
    expect_that!(inline_proto.as_view().has_count(), eq(false));
}

#[gtest]
fn test_from_rust_and_take() {
    let mut owned = DummyMessage::default();
    owned.set_count(123);

    let mut inline_proto = ctor::emplace!(InlineDummyMessage::from_rust(owned));
    expect_that!(inline_proto.as_view().count(), eq(123));

    let taken: DummyMessage = inline_proto.as_mut().take();
    expect_that!(taken.count(), eq(123));
    expect_that!(inline_proto.as_view().has_count(), eq(false));
}

#[gtest]
fn test_view_to_owned_and_merge_via_as_proto_mut() {
    let mut owned = DummyMessage::default();
    owned.set_count(456);

    let mut inline_proto = ctor::emplace!(InlineDummyMessage::ctor_new(()));
    inline_proto.as_mut().as_proto_mut().merge_from(owned.as_view());
    expect_that!(inline_proto.as_view().count(), eq(456));
    // Original owned message is untouched.
    expect_that!(owned.count(), eq(456));

    let mut cloned_owned = DummyMessage::default();
    cloned_owned.copy_from(inline_proto.as_view());
    expect_that!(cloned_owned.count(), eq(456));
}

#[gtest]
fn test_copy_and_move_between_inline_protos() {
    let mut owned = DummyMessage::default();
    owned.set_count(789);

    let mut p1 = ctor::emplace!(InlineDummyMessage::from_rust(owned));
    let p2 = ctor::emplace!(ctor::copy(&*p1));
    expect_that!(p1.as_view().count(), eq(789));
    expect_that!(p2.as_view().count(), eq(789));

    let mut p3 = ctor::emplace!(ctor::mov!(p1.as_mut()));
    expect_that!(p3.as_view().count(), eq(789));
    expect_that!(p1.as_view().has_count(), eq(false));

    p1.as_mut().assign(&*p2);
    expect_that!(p1.as_view().count(), eq(789));

    p3.as_mut().as_proto_mut().set_count(999);
    p1.as_mut().assign(ctor::mov!(p3.as_mut()));
    expect_that!(p1.as_view().count(), eq(999));
    expect_that!(p3.as_view().has_count(), eq(false));

    // Cross-library marker interoperability (`Cpp<TestDummyMessage>` <->
    // `Cpp<OtherLibDummyMessage>`).
    let mut other_lib_proto =
        ctor::emplace!(Cpp::<OtherLibDummyMessage>::ctor_new(ctor::mov!(p1.as_mut())));
    expect_that!(other_lib_proto.as_view().count(), eq(999));
    expect_that!(p1.as_view().has_count(), eq(false));

    p1.as_mut().assign(&*other_lib_proto);
    expect_that!(p1.as_view().count(), eq(999));
    expect_that!(p1.as_mut().assign(ctor::mov!(other_lib_proto.as_mut())), eq(()));
    expect_that!(p1.as_view().count(), eq(999));
    expect_that!(other_lib_proto.as_view().has_count(), eq(false));
}
